const ASSETS={"index.html":"","style.css":"","alt.css":"","app.mjs":"","data.mjs":"","favicon.svg":""};
const mime={html:'text/html;charset=utf-8',css:'text/css',mjs:'text/javascript',svg:'image/svg+xml'};
const RPC='https://rpc.mainnet.arc.io',USDC='0x3600000000000000000000000000000000000000';
function dec(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
async function supply(){const body={jsonrpc:'2.0',id:1,method:'eth_call',params:[{to:USDC,data:'0x18160ddd'},'latest']};const r=await fetch(RPC,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const d=await r.json();return Number(BigInt(d.result))/1e6}
async function ingest(env){const value=await supply();await env.DB.prepare('CREATE TABLE IF NOT EXISTS usdc_supply (day TEXT PRIMARY KEY, value REAL NOT NULL, block INTEGER, source TEXT NOT NULL)').run();const day=new Date().toISOString().slice(0,10);await env.DB.prepare('INSERT INTO usdc_supply(day,value,block,source) VALUES(?,?,?,?) ON CONFLICT(day) DO UPDATE SET value=excluded.value, block=excluded.block').bind(day,value,null,'arc-rpc').run();return {day,value,source:'arc-rpc'}}
async function history(env){try{const r=await env.DB.prepare('SELECT day,value,source FROM usdc_supply ORDER BY day').all();return r.results.map(x=>({date:Math.floor(Date.parse(x.day+'T00:00:00Z')/1000),value:x.value,source:x.source}))}catch(e){const r=await fetch('https://stablecoins.llama.fi/stablecoincharts/Arc?stablecoin=2');const d=await r.json();return d.filter(x=>Number.isFinite(x.totalCirculating?.peggedUSD)).map(x=>({date:Number(x.date),value:x.totalCirculating.peggedUSD,source:'defillama-fallback'}))}}
export default {async fetch(req,env){const u=new URL(req.url);if(u.pathname==='/api/usdc/history')return Response.json(await history(env),{headers:{'cache-control':'no-store'}});if(u.pathname==='/api/ingest'){try{return Response.json(await ingest(env))}catch(e){return Response.json({error:e.message},{status:500})}}const name=u.pathname==='/'?'index.html':u.pathname.slice(1);if(ASSETS[name]){const ext=name.split('.').pop();return new Response(dec(ASSETS[name]),{headers:{'content-type':mime[ext]||'text/plain'}})}return new Response('Not found',{status:404})},async scheduled(_event,env){await ingest(env)}};
